model Testimonial {
  id          String   @id @default(cuid())
  author      String
  role        String?
  quote       String
  avatarEmoji String?
  rating      Int      @default(5)
  published   Boolean  @default(false)
  sortOrder   Int      @default(0)
  createdAt   DateTime @default(now())
}

// ---- Game servers as a separate product with their own pricing ----
model GamePlan {
  id           String   @id @default(cuid())
  gameFamily   String // minecraft, valheim, rust, palworld, cs2, terraria, ...
  name         String // e.g. "Minecraft — 4 GB / 20 slots"
  ramMB        Int
  cpuCores     Int      @default(2)
  diskGB       Int
  slots        Int? // player slots (nullable)
  priceCents   Int // retail price the customer pays (per term) — the REGULAR/renewal rate
  /// GRANDFATHER PROGRAM (2026-09-17): mirrors Plan.introPriceCents/introTermMonths
  /// exactly — a lower first-term price that renews at the regular `priceCents`
  /// above. Read by the same generic lib/intro-pricing.ts helpers VPS already
  /// uses (planIntroMonthlyCents/planIntroTermMonths take a `{priceCents}`-shaped
  /// row, so a GamePlan works with zero new code there). NULL introTermMonths
  /// means the WHOLE first term (any length) bills at introPriceCents.
  introPriceCents Int?
  introTermMonths Int?
  termMonths   Int      @default(1)
  basePlanId   String // the VPS Plan used to size/provision the VM
  basePlan     Plan     @relation(fields: [basePlanId], references: [id])
  osTemplateId String? // the game's OsTemplate (image) to deploy
  featured     Boolean  @default(false)
  active       Boolean  @default(true)
  sortOrder    Int      @default(0)
  createdAt    DateTime @default(now())
  servers      Server[]
}

/// Mod-manager CATALOG: an installable mod/plugin for a game family. One row per
/// mod per family; customers browse these and one-click install onto their server.
/// Seeded from the per-game mod deep-dive research (name/category/source/id).
model GameMod {
  id               String      @id @default(cuid())
  gameFamily       String // minecraft, rust, valheim, cs2, ark-ase, ark-asa, palworld, terraria, project-zomboid, ...
  name             String
  slug             String // stable per-family kebab identifier
  category         String // Admin, Protection, Economy, Performance, Content, QoL, ...
  // Where it comes from + how the installer fetches it. One of: modrinth, curseforge,
  // hangar, spigotmc, steam_workshop, thunderstore, umod, codefling, nexus, ficsit,
  // rocketmod, factorio_portal, mcpedl, github, mod_io, vintagestory_moddb, manual.
  source           String
  sourceId         String? // workshop id / curseforge project id / modrinth slug / etc.
  url              String?
  modStringId      String? // e.g. Project Zomboid's Mods= string id (distinct from the numeric Workshop id)
  appliesToVariant String? // restrict to a loader/variant (e.g. "paper", "oxide", "carbon"); null = any
  description      String?
  iconUrl          String?
  popularity       Int         @default(0) // higher = more popular (sort key)
  paid             Boolean     @default(false)
  featured         Boolean     @default(false)
  active           Boolean     @default(true)
  createdAt        DateTime    @default(now())
  updatedAt        DateTime    @updatedAt
  installs         ServerMod[]

  // ── Verified upstream facts (scripts/verify-gamemods.ts) ─────────────────
  // Everything below is READ FROM THE SOURCE API, never hand-written: the
  // storefront's previous star ratings and install counts were computed from a
  // hash of the slug, and the fix is not better guesses but real numbers.
  /// Game versions the source says this supports. Empty = the source has no
  /// version list (uMod, Steam Workshop), which is not the same as "none".
  gameVersions    String[]  @default([])
  /// Loaders/platforms the source lists (paper, spigot, fabric, forge, …).
  loaders         String[]  @default([])
  /// Real download count from the source. Null where the source exposes none.
  downloads       Int?
  /// Primary file size in bytes — the objective half of the impact rating.
  fileBytes       Int?
  /// How many other projects the latest build requires.
  dependencyCount Int       @default(0)
  /// "required" | "optional" | "unsupported" — a client-only mod cannot be
  /// installed on a server at all, and the catalogue should not offer it.
  serverSide      String?
  /// Resource weight shown as a warning: light | moderate | heavy.
  impact          String    @default("light")
  /// Why this one is heavy, in the customer's words, on its own card.
  impactNote      String?
  /// When the fields above were last confirmed against the source.
  verifiedAt      DateTime?
  /// False once a verification pass fails to find the project upstream — a
  /// dead entry must stop being offered rather than 404 at install time.
  upstreamOk      Boolean   @default(true)
  /// Why upstreamOk is false, in plain language ("removed from Modrinth",
  /// "project archived"). Null while upstreamOk is true or never verified.
  upstreamNote    String?
  /// Real SPDX-ish license id/name from the source (Modrinth's `license.id`,
  /// e.g. "MIT", "GPL-3.0-only", "All Rights Reserved"). String, not a Prisma
  /// enum, matching this file's convention for open-ended source vocabularies
  /// (see `source` above) — sources invent new license strings constantly.
  /// Null where the source doesn't publish one or the mod hasn't been
  /// verified yet (scripts/verify-gamemods.ts).
  license         String?
  /// Real gallery/screenshot images from the source (Modrinth's project
  /// `gallery[]`, CDN-hosted, hotlinkable). Empty when the source has none —
  /// most plugins/mods don't carry a gallery; resource/texture/shader packs
  /// usually do. This is the mod's actual screenshot strip, not iconUrl
  /// repeated — iconUrl stays the small square logo shown on cards.
  galleryUrls     String[]  @default([])
  /// Real creator/team name from the source (Modrinth project members,
  /// Spiget author lookup, Thunderstore package namespace). Null when the
  /// source doesn't resolve one. No "Follow" button anywhere reads this —
  /// there's no real follow relationship to back one.
  authorName      String?
  /// Real avatar URL for authorName, when the source publishes one
  /// (Modrinth member avatar_url). Null otherwise.
  authorAvatarUrl String?
  /// The source's own LONGER project-page body, when it publishes one
  /// distinct from the short one-line `description` tagline above — real
  /// Markdown, not a summary or a rewrite. Today only Modrinth's `body` field
  /// (its full project-page content, confirmed live to run into the
  /// thousands of characters on real projects) populates this; GitHub's repo
  /// metadata has no equivalent longer field to fetch (its `description` IS
  /// the whole of what GitHub offers for a one-liner — see
  /// scripts/backfill-modrinth-descriptions.ts's file header for the
  /// per-source investigation). Null for every mod this hasn't been
  /// backfilled for yet, or whose source has nothing longer to offer —
  /// never a guess or a copy of `description`.
  longDescription String?   @db.Text

  /// The mod's REAL last-modified timestamp on its OWN upstream source —
  /// never derived from this row's own `updatedAt` above, which only marks
  /// when WE last touched the row (a bulk re-import, a verify pass) and says
  /// nothing about when the mod's actual author last shipped anything. Null
  /// until backfilled/verified against the source. Populated by
  /// scripts/backfill-upstream-updated.ts from the real, confirmed-live field
  /// per source: Modrinth's project `updated` (its bulk `/v2/projects?ids=`
  /// response — NOT `date_modified`, which doesn't exist on the real API),
  /// GitHub's repo `pushed_at`, Thunderstore's latest-version `date_created`
  /// (its v1 community catalogue's real per-version date field — no separate
  /// package-level "updated" field in that response), Steam Workshop's
  /// `time_updated` from GetPublishedFileDetails, and mod.io's `date_updated`.
  /// A "Recently Updated" rail (lib/mods-catalog.ts's listRecentlyUpdatedMods)
  /// filters out nulls rather than treating "never verified" as "not recent".
  upstreamUpdatedAt DateTime?

  ratings         ModRating[]

  @@unique([gameFamily, slug])
  @@index([gameFamily, category])
  @@index([upstreamUpdatedAt])
  /// Added 2026-09-21 — the real query-plan fix for /mods and /dashboard/nxlabs
  /// feeling unresponsive after the catalogue grew 124 -> 45,766 rows in one
  /// session. `EXPLAIN ANALYZE` against real production data (see
  /// docs/DOCUMENTATION.md's dated entry) confirmed every one of
  /// queryCatalogMods' ORDER_BY variants (lib/mods-catalog.ts) plus
  /// listFeaturedMods/listTopDownloadedMods/listTopRatedMods was doing a
  /// Seq Scan + top-N heapsort over the whole table (45,761 live rows) on
  /// every call — ~25-70ms each today (small enough to still feel invisible

