import type { GameFamily } from "@/lib/games";

/**
 * PREVIEW-ONLY sample data for the three new game-landing DIRECTIONS
 * (components/marketing/gamelanding/*). Nothing here touches the live
 * GameLandingPage or any *-server-hosting route — it exists purely so the
 * preview routes render with realistic, game-specific content.
 *
 * Plans/prices are pulled from the real live pages (rust-server-hosting,
 * satisfactory-server-hosting, palworld) so the mock reads true.
 *
 * Social proof is split into two clearly-distinct things (2026-08-29 revision):
 *   - The real aggregate rating/count is <ReviewBadges/> (Google/Trustpilot/
 *     HostAdvice), rendered by the route page and passed in as a prop. That is
 *     the only place a star average or review count is ever shown.
 *   - `reviews` below are ILLUSTRATIVE example feedback, not real customer
 *     submissions — no invented personal names and no per-quote star rating
 *     (that would imply a specific measured score). Attribution is a generic
 *     `role` string (e.g. "Rust wipe admin") and every render of this data is
 *     required to visibly label it as illustrative/example content.
 */

export type PreviewPlan = {
  id: string;
  /** Short tier label, e.g. "Wipe" / "Community". */
  tier: string;
  /** RAM headline, e.g. "6 GB". */
  ram: string;
  /** Displayed price, e.g. "$17.99". Rendered with a trailing "/mo". */
  price: string;
  /** Right-aligned spec meta, e.g. "60 slots" or "4 vCPU · 120 GB NVMe". */
  meta: string;
  /**
   * Advertised player-slot capacity for this plan, when it has one. Drives the
   * interactive pricing configurator's player-count → plan matching. Omitted for
   * VPS-style plans (e.g. Satisfactory) that are sized by RAM rather than slots —
   * those fall back to the fitted RAM curve in lib/game-player-recommend.
   */
  slots?: number;
  blurb: string;
  popular?: boolean;
  features: string[];
  /**
   * Regular/renewal MONTHLY price (e.g. "$17.99"), set ONLY when `price` above is
   * a discounted first-term intro rate. Added 2026-09-19 for the game×location
   * matrix (lib/marketing/gameLocationLandings.ts's adapter), which prices plans
   * from live `GamePlan.priceCents`/`introPriceCents` and must disclose the
   * renewal the same way PricingGrid.tsx already does — optional so every
   * existing PREVIEW_GAMES entry below (flat `price`, no intro/renewal split)
   * renders exactly as before.
   */
  renewalPrice?: string;
};

/** Icon keys resolved to real <Icon*> components inside the client kit. */
export type IconKey =
  | "bolt"
  | "apps"
  | "terminal"
  | "shield"

import { NextRequest, NextResponse } from "next/server";
import NXM_LIVE_ROUTES from "./app/nxm/_data/live-routes.json";

function hostList(envVar: string | undefined): string[] {
  return (envVar ?? "")
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
}

// Every file actually committed under public/ -- logos, game art, flags,
// brand assets, blog images, docs, fonts. None of it is per-customer or
// sensitive; it's already served unauthenticated at the same path on the
// main site, so exposing it on the admin/staff hosts too doesn't defeat the
// isolation below (that's about app pages like /dashboard, not static
// files). Without this, every <img> under public/ 404s on the admin/staff
// hosts -- found live 2026-09-14 when the What's New announcement preview
// (game art, screenshots, the Nxeon logo) rendered as broken images in the
// admin panel while the identical page worked fine for customers.
const STATIC_ASSET_RE =
  /\.(?:png|jpe?g|gif|webp|svg|ico|mp4|webm|woff2?|css|json|txt|md|html)$/i;

/**
 * Reachable on every host regardless of portal mode: Next internals, the API
 * surface every portal's own client code calls (chat SSE, uploads, etc.),
 * the auth utility pages every login form links to, and static files under
 * public/. Everything else is scoped to exactly one portal below.
 */
function isUniversallyAllowed(pathname: string): boolean {
  return (
    pathname.startsWith("/_next") ||
    pathname.startsWith("/api/") ||
    pathname === "/favicon.ico" ||
    pathname.startsWith("/.well-known/") ||
    pathname === "/forgot-password" ||
    pathname === "/reset-password" ||
    // Both portal layouts redirect a staff/admin account without 2FA here to
    // enroll (enforce_staff_2fa) -- account security settings aren't
    // customer-specific, and blocking this would stand between a legitimate
    // staff member and the one page that lets them satisfy the requirement.
    pathname === "/dashboard/settings" ||
    STATIC_ASSET_RE.test(pathname)
  );
}

/**
 * Confines the admin/staff hostnames to exactly their own portal.
 *
 * app/admin/layout.tsx and app/staff/layout.tsx already refuse the WRONG
 * direction -- /admin and /staff 404 on any host that isn't their own
 * NXEON_ADMIN_HOSTS/NXEON_STAFF_HOSTS. But nothing stopped the REVERSE: the
 * admin/staff hostnames proxy to the exact same Next.js backend as the main
 * site, so /dashboard, /login, /register, and every marketing page were
 * equally reachable there too -- confirmed live 2026-09-02, a customer's full
 * dashboard (wallet, deploy, domains) loading on the staff-only subdomain.
 * Not a data leak (they only ever saw their own account), but it defeats the
 * point of a separate, minimal, operations-only surface, and reduces
 * whatever "hard to guess" value the admin subdomain has by leaving it fully
 * browsable/indexable as a second copy of the public site.
 *

import Link from "next/link";
import type { Metadata } from "next";
import { GameLandingCombined } from "@/components/marketing/gamelanding/GameLandingCombined";
import { PREVIEW_GAMES } from "@/components/marketing/gamelanding/data";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { Section, SectionTitle } from "@/components/marketing/primitives";
import { FaqJsonLd, ProductOffersJsonLd, APP_URL } from "@/components/marketing/StructuredData";

/**
 * LIVE — flagship "Combined" game-landing design, Wave 7 rollout.
 *
 * CONTENT FIX, not just a design swap: this route's family is "ark" (ARK:
 * Survival EVOLVED, the original 2015 game, Steam app 376030), but the
 * previous version of this page had its entire copy — title, hero, FAQ,
 * steps — swapped with ARK: Survival ASCENDED content (Studio Wildcard's
 * separate UE5 remake, family "arkasa", its own page at
 * /ark-survival-ascended-server-hosting). That was a leftover copy-paste bug,
 * confirmed by the comment at the top of ark-survival-ascended-server-hosting
 * /page.tsx ("the original ARK: Survival Evolved, which stays live at
 * /ark-server-hosting"). This rewrite is genuinely about Survival Evolved.
 *
 * This also converts the page from self-managed VPS framing (customer SSHes
 * in and runs SteamCMD themselves) to the real one-click managed hosting
 * that just went live (prisma/seed-wave7-games.ts — real OsTemplate +
 * GamePlan rows, confirmed orderable in the deploy wizard).
 *
 * PREVIEW_GAMES.ark was authored directly from those real seeded GamePlan
 * rows (8 GB/20 slots $14.99, 16 GB/50 slots $27.99 popular, 32 GB/100 slots
 * $49.99) — no price override needed here.
 *
 * Art: family "ark"'s art slug is "ark-asa" (see lib/games.ts GAME_ART_SLUG).
 * Confirmed via that file's own comment that "ark-asa" actually contains
 * genuine ARK: Survival EVOLVED key art despite the confusing slug name (a
 * separate, already-documented mislabeling issue) — so the art is correct
 * for this family and no art change was made alongside this copy fix.
 *
 * FAQ + related-links sections below follow the same pattern as
 * rust-server-hosting/page.tsx, since GameLandingCombined doesn't render its
 * own FAQ/related sections.
 */

export const metadata: Metadata = {
  title: "ARK: Survival Evolved Server Hosting — Instant Setup",
  description:
    "Managed ARK: Survival Evolved server hosting from $14.99/mo. Full FTP access, your own admin password, and instant setup on our low-latency Singapore or Germany network.",
  alternates: { canonical: "/ark-server-hosting" },
  openGraph: {
    type: "article",
    title: "ARK: Survival Evolved Server Hosting — Instant Setup",
    description:
      "Managed ARK: Survival Evolved hosting: full FTP access, your own admin password, and instant setup on our low-latency Singapore or Germany network. From $14.99/mo.",
    url: `${APP_URL}/ark-server-hosting`,
  },
};

const GAME = PREVIEW_GAMES.ark;

const FAQ = [
  {
    q: "Is this ARK: Survival Evolved or ARK: Survival Ascended?",
    a: "This page is the original ARK: Survival Evolved (2015, Steam app 376030). Survival Ascended is Studio Wildcard's separate Unreal Engine 5 remake, hosted on its own plans — see our ARK: Survival Ascended hosting page if that's the one you want.",
  },
  {
    q: "How much RAM does an ARK: Survival Evolved server need?",
    a: "8 GB comfortably runs a small tribe on a single map, 16 GB is the recommended baseline for a fuller 50-slot tribe server, and 32 GB gives a busy multi-tribe alliance server room to breathe. Our three plans map directly to those tiers.",
  },
  {
    q: "Can I install mods?",
    a: "Yes. Full FTP file access lets you upload mods and edit GameUserSettings.ini and Game.ini directly to tune taming rates, difficulty, and mod lists — no host-imposed limits.",
  },
  {
    q: "What ports does ARK: Survival Evolved use?",
    a: "The game ports are 7777 and 7778 (UDP), with an RCON/query port on 27020 (TCP). On a managed Nxeon server those are opened for you and the connect details are provided automatically.",
  },
  {
    q: "Is this managed, or do I set it up myself?",
    a: "Fully managed one-click hosting — no SteamCMD or server install to run yourself. Order a plan and it's provisioned and online in minutes, with your admin password ready to set and full FTP access from the start.",
  },
];

"use client";

import { useState } from "react";
import Link from "next/link";
import { IconCheck } from "./icons";
import { planTip, planAudience } from "./planTips";
import { termPriceCents, ANNUAL_TERM_MONTHS, vpsEffectiveMonthly } from "@/lib/billing-terms";
import { planIntroMonthlyCents } from "@/lib/intro-pricing";
import { useDisplayMoney } from "@/components/currency/CurrencyContext";
import { deployHref, type DeployService } from "@/lib/deploy-intent";

export type PlanCard = {
  id: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  priceCents: number;
  storageTier: string;
  /**
   * LOW introductory MONTHLY price (cents) for the first term — the plan
   * RENEWS at `priceCents`. Optional: most callers pass a raw `db.plan` row
   * straight through (it carries `introPriceCents` at runtime even though this
   * narrower display type doesn't declare it), in which case `planIntroMonthlyCents`
   * reads it directly and this field is never needed. Set it explicitly only when
   * the caller built a plain object that dropped the original DB row.
   */
  introMonthlyCents?: number | null;
  /**
   * Player-slot count — GamePlan rows only (a `db.gamePlan` row mapped to this
   * shape by its caller). Shown as a headline feature instead of the generic
   * vCPU/RAM/disk framing when `service="game"`, since "slots" is the number a
   * game-hosting shopper actually cares about.
   */
  slots?: number | null;
};

function planFeatures(p: PlanCard, service: DeployService): string[] {
  const disk = p.storageTier === "hdd" ? "HDD storage" : "NVMe SSD storage";
  const isGame = service === "game";
  return [
    ...(isGame && p.slots ? [`${p.slots} player slots`] : []),
    `${p.cpuCores} vCPU core${p.cpuCores > 1 ? "s" : ""}`,
    `${(p.ramMB / 1024).toFixed(p.ramMB % 1024 ? 1 : 0)} GB RAM`,
    `${p.diskGB} GB ${disk}`,
    `${p.bandwidthTB} TB bandwidth`,
    isGame ? "Full file access (FTP)" : "Full root access",
    "Free DDoS protection",
  ];
}

/**
 * `service`/`gameFamily`: which product these plans deploy as. Defaults to
 * "vps" (unchanged behavior for every existing caller — VPS `Plan` rows
 * deployed via `?product=vps&plan=<Plan.id>`). Pass `service="game"` with
 * `gameFamily` when `plans` are `GamePlan` rows mapped to this shape (see
 * lib/marketing/gameLocationLandings.ts) so each card's "Deploy now" link
 * carries `gameFamily` + `gamePlanId` instead of misrouting a GamePlan's id
 * through the VPS `plan` param.

 * comes straight from them.
 */
export function buildGameLocationLanding(
  combo: GameLocationCombo,
  plans: GamePlanRow[],
): BuiltLanding & { gameFamily: GameFamily; productName: string } {
  const { location: loc, family } = combo;
  const game = gameName(family);
  const flavor = GAME_FLAVOR[family];
  const genres = GAME_GENRES[family] ?? [];
  const from = gameFromLabel(plans);
  const near3 = listPhrase(loc.nearby.slice(0, 3));
  const flag = locationFlag(loc);
  const lowPing = canClaimLatency(loc);

  const ramValues = plans.map((p) => p.ramMB).filter((n) => Number.isFinite(n));
  const slotValues = plans.map((p) => p.slots).filter((n): n is number => typeof n === "number");
  const minRamGB = ramValues.length ? Math.min(...ramValues) / 1024 : null;
  const maxRamGB = ramValues.length ? Math.max(...ramValues) / 1024 : null;
  const minSlots = slotValues.length ? Math.min(...slotValues) : null;
  const maxSlots = slotValues.length ? Math.max(...slotValues) : null;

  const sizingLine =
    minRamGB != null && maxRamGB != null
      ? `Plans here range from ${minRamGB % 1 ? minRamGB.toFixed(1) : minRamGB} GB up to ${maxRamGB % 1 ? maxRamGB.toFixed(1) : maxRamGB} GB` +
        (minSlots != null && maxSlots != null ? `, ${minSlots}–${maxSlots} player slots` : "") +
        " — pick the size that matches your group."
      : "Pick the size that matches your group; every tier scales with one click.";

  const metaTitle = `${flag} ${loc.name} ${game} Server Hosting — ${lowPing ? "Low-Ping" : "Managed"} Servers, from ${from}/mo`;
  const metaDescription = `${loc.name} ${game} server hosting for ${loc.regionLong}. ${game} is ${flavor}. Dedicated resources, full file access, DDoS protection and instant setup, from ${from}/mo.`;

  const useCaseContent = {
    eyebrow: `${flag} ${loc.name} ${game.toLowerCase()} hosting`,
    title: `${lowPing ? "Low-ping" : "Reliable"} ${game} servers in`,
    highlight: loc.name,
    sub: `Dedicated, game-ready ${game} servers built for ${loc.regionLong} — full file access, DDoS protection and instant setup, from ${from}/mo.`,
    intro: [
      `${game} is ${flavor}. Run one for ${loc.audience} players and the same thing decides whether it feels great or frustrating as any other online game: the round trip between your players and the server. ${loc.hub}`,
      `Nxeon runs ${game} on the same full-root NVMe platform as every other title in the catalog: dedicated CPU and memory per server (no oversold host stealing your tick rate), full file access for mods, plugins and configs, always-on DDoS protection, and instant setup so your world or match is online within minutes.`,
      `This page is tuned for ${articleFor(loc.audience)} ${loc.audience} audience across ${near3}${genres.length ? ` looking for a ${genres[0].toLowerCase()}-focused ${game} server` : ""} — deploy, invite your players, and resize with one click as your community grows.`,
    ],
    whyTitle: `Built for ${game} in ${loc.name}`,
    why: [
