   for Minecraft must not greet the customer who has since picked Rust. When
   it opens, bring it into view by scrolling the WINDOW (never
   scrollIntoView — see tryNext's note on the overflow-hidden deck). */
const [customOpen, setCustomOpen] = useState(false);
useEffect(() => { setCustomOpen(false); }, [o.service, o.gameFamily]);
useEffect(() => {
  if (!customOpen) return;
  const id = requestAnimationFrame(() => {
    const el = document.getElementById("custom-builder");
    if (!el) return;
    const r = el.getBoundingClientRect();
    if (r.top > window.innerHeight - 160 || r.top < 80) {
      window.scrollTo({ top: window.scrollY + r.top - 96, behavior: "smooth" });
    }
  });
  return () => cancelAnimationFrame(id);
}, [customOpen]);
