// ── Step 2: copy baseline tiers for families staging never got ───────────
// Guard (2026-09-29): only for a family that has ZERO active tiers OTHER
// than this script's own gp4t-baseline-* rows. Without this, Step 2's
// upsert-by-OWN-id is safe to re-run on the SAME database (staging, where
// it already ran) but not a first run against PRODUCTION — prod already
// has its own real rows for all 5 of these families, under normal cuids
// that never match "gp4t-baseline-*", so the id-based existence check
// would find nothing and silently duplicate every one of them (e.g. dayz
// would end up with its real 3 tiers PLUS 3 byte-identical baseline
// copies). This guard makes the step a genuine no-op wherever a family
// isn't actually missing, on staging today and on prod whenever this is
// eventually run there.
const baselineFamilies = [...new Set(BASELINE_FOR_MISSING_FAMILIES.map((s) => s.gameFamily))];
const baselineIds = new Set(BASELINE_FOR_MISSING_FAMILIES.map((s) => s.id));
const familiesAlreadyReal = new Set<string>();
for (const fam of baselineFamilies) {
  const rows = await db.gamePlan.findMany({ where: { gameFamily: fam, active: true }, select: { id: true } });
  if (rows.some((r) => !baselineIds.has(r.id))) familiesAlreadyReal.add(fam);
}
let baselineCreated = 0;
let baselineUpdated = 0;
let baselineSkipped = 0;
for (const spec of BASELINE_FOR_MISSING_FAMILIES) {
  if (familiesAlreadyReal.has(spec.gameFamily)) {
    baselineSkipped++;
    continue;
  }
  const basePlan = pickBasePlan(spec.ramMB);

